------------ import ------------
local KTool = CS.Engine.Lib.KTool
------------ import ------------

------------ define ------------
local Image = typeof(CS.UnityEngine.UI.Image)
local CanvasGroup = typeof(CS.UnityEngine.CanvasGroup)
local UISwitchImage = typeof(CS.Game.Native.Common.UISwitchImage)
local BehaviourActionType = typeof(CS.Engine.Lib.BehaviourAction)

-- 遥感位移量小于此值时, 不会扩大 outCircle
local MagnitudeMinThreshold = 0.2
-- outCircle 缩放区间
local outCircleMinScale = 0.7
local outCircleMaxScale = 1
-- outCircle 缩放区间
local directionArrowMinScale = 1.35
local directionArrowMaxScale = 1.2
-- 切换图标的 阈值
local directionArrowSwitchThreshold = 0.9

local alphaChangeSpeed = 0.1

local HideAlpha = 0
local ShowAlpha = 1
------------ define ------------

--- from: Assets/BundleResources/Prefabs/Joystick/EasyTouchControls.prefab
---@class ETCJoystickCN
---@field Env                           	ETCJoystickCN                                     
---@field controller                    	Engine.Modules.LuaBehaviour | Engine.UI.UILuaDialog
---@field directionArrow                	UnityEngine.RectTransform        
---@field backGroundDecorate            	UnityEngine.RectTransform               
---@field backGround                    	UnityEngine.RectTransform    
---@field thumb                         	UnityEngine.RectTransform   
---@field joystick                          ETCJoystickCN                
local ETCJoystickCN = {}

------------ lifeCycle ------------
function ETCJoystickCN:Awake()
    self.canvasGroup = nil

    self._tgtAlpha = nil
    self._currentAlpha = nil

    self._thumbImage = nil
    self._backGroundImage = nil
    self._backGroundDecorateImage = nil
    self._directionArrowImage = nil

    self._arrowUISwitchImage = nil

    -- self._behaviourAction = nil
    ---@type Engine.Lib.BehaviourAction
    local behaviourAction = KTool.GetOrAddComponent(self.controller.gameObject, BehaviourActionType)
    behaviourAction.UpdateAction = Bind(self, self.Update)
    self._behaviourAction = behaviourAction

    self._onMoveStartCallback = nil
    self._onMoveEndCallback = nil

    self.canvasGroup = KTool.GetComponent(self.controller.gameObject, CanvasGroup)
end

function ETCJoystickCN:OnDestroy()
    self.canvasGroup = nil

    self._tgtAlpha = nil
    self._currentAlpha = nil

    self._thumbImage = nil
    self._backGroundImage = nil
    self._backGroundDecorateImage = nil
    self._directionArrowImage = nil
    
    self._arrowUISwitchImage = nil

    if not isNull(self._behaviourAction) then
        self._behaviourAction.UpdateAction = nil
    end 
    self._behaviourAction = nil

    if not isNull(self.joystick) then
        self.joystick.onMoveStart:RemoveListener(self._onMoveStartCallback)
        self.joystick.onMoveEnd:RemoveListener(self._onMoveEndCallback)
    end
    self._onMoveStartCallback = nil
    self._onMoveEndCallback = nil
end

function ETCJoystickCN:Start()
    self._tgtAlpha = HideAlpha
    self._currentAlpha = ShowAlpha  -- 因为这些ui默认是开启显示的... 

    self._thumbImage = KTool.GetComponent(self.thumb.gameObject, Image)
    self._backGroundImage = KTool.GetComponent(self.backGround.gameObject, Image)
    self._backGroundDecorateImage = KTool.GetComponent(self.backGroundDecorate.gameObject, Image)
    self._directionArrowImage = KTool.GetComponent(self.directionArrow.gameObject, Image)

    self._arrowUISwitchImage = KTool.GetComponent(self.directionArrow.gameObject, UISwitchImage)

    

    self._onMoveStartCallback = Bind(self, self.OnMoveStart)
    self._onMoveEndCallback = Bind(self, self.OnMoveEnd)
    self.joystick.onMoveStart:AddListener(self._onMoveStartCallback)
    self.joystick.onMoveEnd:AddListener(self._onMoveEndCallback)
end

function ETCJoystickCN:Update()
    local x = self.joystick.axisX.axisValue
    local y = self.joystick.axisY.axisValue

    local k = Mathf.Sqrt(x*x + y*y)

    ------- outCircle 在跑步时会变大 -------:
    -- 下面部分 magic number 最好都做成公开参数;
    local k2 = self:Remap(MagnitudeMinThreshold, 1, 0, 1, k)

    k2 = k2*k2*k2; -- 三阶曲线
    k2 = Mathf.Clamp01(k2);
    local scale1 = self:Remap( 0, 1, outCircleMinScale, outCircleMaxScale, k2 );
    self.backGround.localScale = Vector3.New( scale1,scale1,scale1 );

    local scale2 = self:Remap( 0, 1, directionArrowMinScale, directionArrowMaxScale, k2 );
    self.directionArrow.localScale = Vector3.New( scale2,scale2,scale2 );


    ------- directionArrow 跟随方向旋转 -------:
    local dir = (self.thumb.position - self.joystick.gameObject.transform.position).normalized;
    local angle = Vector3.SignedAngle( Vector3.up, dir, Vector3.forward );
    self.backGround.localRotation = Quaternion.Euler( 0,0, angle );

    ----- 控制 几个 ui 图标的半透明程度 ------:
    local newAlpha = Mathf.Lerp( self._currentAlpha, self._tgtAlpha, alphaChangeSpeed ) -- 透明度渐变

    if Mathf.Abs(newAlpha - self._currentAlpha) > 0.0001 then
        self._currentAlpha = newAlpha;
        local color = Color.New( 1,1,1, self._currentAlpha );
        self._thumbImage.color = color;
        self._backGroundImage.color = color;
        self._backGroundDecorateImage.color = color;
        self._directionArrowImage.color = color;
    end

    ----- 切换 方向箭头 图标 -----:
    self._arrowUISwitchImage.Status = k > directionArrowSwitchThreshold and 2 or 1;

    ----- 网格ui 跟着 thumb 移动 -----:
    self.backGroundDecorate.localPosition = self.thumb.localPosition * 0.5;

end
------------ lifeCycle ------------

------------ easy touch callback ------------
function ETCJoystickCN:OnMoveStart()
    self._tgtAlpha = ShowAlpha
end

function ETCJoystickCN:OnMoveEnd()
    self._tgtAlpha = HideAlpha
end
------------ easy touch callback ------------


function ETCJoystickCN:Active()
    self.canvasGroup.alpha = 1
    self.canvasGroup.interactable = true;
    self.canvasGroup.blocksRaycasts = true;

    self._behaviourAction.UpdateAction = Bind(self, self.Update)
end

function ETCJoystickCN:Deactive()
    self.canvasGroup.alpha = 0
    self.canvasGroup.interactable = false;
    self.canvasGroup.blocksRaycasts = false;

    self._behaviourAction.UpdateAction = nil
end

function ETCJoystickCN:Remap(t1, t2, s1, s2, x)
    return ((x - t1) / (t2 - t1) * (s2 - s1) + s1);
end

return ETCJoystickCN